//! Reading real workbook files end to end.
//!
//! These run against files that were not generated by this crate's own fixtures: genuine
//! `.xlsx` exports and a hand-built `.ods`. They are what catches the difference between
//! "parses the shape I expected" and "reads the file a tool actually wrote".

mod common;

use cellar::{open_workbook, Data, Error, Format, HeaderRow, Reader};
use std::path::PathBuf;

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("data")
        .join(name)
}

/// A nine-sheet report produced by a real scan tool, with strings, integers and long text.
#[test]
fn reads_a_real_multi_sheet_workbook() {
    let mut workbook = open_workbook(fixture("chanora.xlsx")).expect("workbook should open");
    assert_eq!(workbook.format(), Format::Xlsx);

    let expected = [
        "Scan Information",
        "Summary",
        "Components",
        "Vulnerabilities",
        "Vulnerability exploitability",
        "Identifications",
        "Comments",
        "Licenses",
        "Dependency Analysis",
    ];
    assert_eq!(workbook.sheet_names(), expected);

    let scan = workbook.worksheet_range("Scan Information").unwrap();
    assert_eq!(
        scan.get((0, 0)),
        Some(&Data::String("Scan Information".into()))
    );
    assert_eq!(scan.get((1, 0)), Some(&Data::String("Scan Name".into())));
    // A plain string cell from the shared string table.
    assert_eq!(
        scan.get((1, 1)),
        Some(&Data::String("chanora-v0.2.0-beta.1".into()))
    );
    // Embedded spaces are preserved exactly.
    assert_eq!(
        scan.get((4, 1)),
        Some(&Data::String(" fossid (fossid)".into()))
    );

    let summary = workbook.worksheet_range("Summary").unwrap();
    assert_eq!(
        summary.rows().next().unwrap(),
        &[
            Data::String("License".into()),
            Data::String("SPDX Identifier".into()),
            Data::String("Amount".into()),
        ]
    );
    assert_eq!(summary.get((1, 1)), Some(&Data::String("MIT".into())));
}

/// Numeric cells arrive as numbers, including the ones that happen to be whole.
#[test]
fn numeric_cells_keep_their_type() {
    let mut workbook = open_workbook(fixture("chanora.xlsx")).unwrap();
    let range = workbook.worksheet_range("Identifications").unwrap();
    assert_eq!(range.get_size(), (389, 21));

    // Column 18 of this export counts hits, including zeroes.
    let zeroes = range
        .cells()
        .filter(|(r, c, v)| *c == 18 && *r < 6 && **v == Data::Int(0))
        .count();
    assert!(zeroes > 0, "expected some integer zero cells");
    assert_eq!(
        range.get((4, 18)),
        Some(&Data::Int(2)),
        "row 5 records two hits"
    );

    // The long licence text lives in one cell; a partial read would show up as truncation.
    let licences = workbook.worksheet_range("Licenses").unwrap();
    let text = licences.get((1, 3)).unwrap().as_string().unwrap();
    assert!(text.starts_with(" MIT License"));
    assert!(text.contains("THE SOFTWARE IS PROVIDED"));
    assert!(text.contains("OUT OF OR IN CONNECTION"));
}

/// The header-row setting trims the range so the header becomes its first row.
#[test]
fn header_row_trims_the_range() {
    let mut workbook = open_workbook(fixture("chanora.xlsx")).unwrap();
    let full = workbook.worksheet_range("Summary").unwrap();
    assert_eq!(full.get((0, 0)), Some(&Data::String("License".into())));

    workbook.with_header_row(HeaderRow::Row(2));
    let trimmed = workbook.worksheet_range("Summary").unwrap();
    assert_eq!(trimmed.height(), full.height() - 1);
    // Coordinates stay absolute, so the trimmed range now begins at row 1 rather than row 0.
    assert_eq!(trimmed.start(), (1, 0));
    assert_eq!(
        trimmed.get((1, 0)),
        Some(&Data::String("MIT License".into()))
    );
    assert_eq!(trimmed.get((0, 0)), None);
    // Iterating rows is unaffected by the shift: the first row is the header.
    assert_eq!(
        trimmed.rows().next().unwrap()[0],
        Data::String("MIT License".into())
    );
}

/// An OpenDocument file exercises value types that OOXML spells differently.
#[test]
fn reads_an_ods_workbook() {
    let mut workbook = open_workbook(fixture("sample.ods")).expect("workbook should open");
    assert_eq!(workbook.format(), Format::Ods);
    assert_eq!(workbook.sheet_names(), ["Sheet1", "Second Sheet"]);
    assert_eq!(
        workbook.defined_names(),
        [("MyRange".to_string(), "$Sheet1.$A$2:$B$3".to_string())]
    );

    let range = workbook.worksheet_range("Sheet1").unwrap();
    assert_eq!(
        range.get((0, 0)),
        Some(&Data::String("Name".into())),
        "the header rows container still yields rows"
    );
    assert_eq!(range.get((1, 0)), Some(&Data::String("alpha".into())));
    assert_eq!(range.get((1, 1)), Some(&Data::Float(1.5)));
    assert_eq!(range.get((2, 1)), Some(&Data::Int(2)));
    assert_eq!(range.get((3, 0)), Some(&Data::Bool(true)));
    assert_eq!(range.get((3, 1)), Some(&Data::Float(0.25)));
    assert_eq!(
        range.get((3, 2)),
        Some(&Data::DurationIso("PT1H30M".into()))
    );
    assert!(range.get((1, 2)).unwrap().as_date().is_some());

    // Empty padding cells are skipped without shifting the following value.
    assert_eq!(
        range.get((4, 5)),
        Some(&Data::String("after-padding".into()))
    );
    assert_eq!(range.get((4, 2)), Some(&Data::Float(3.5)));

    // `<text:s>` runs and line breaks inside a paragraph.
    assert_eq!(range.get((5, 0)), Some(&Data::String("a   b\nc".into())));
    // Two paragraphs in one cell join with a newline.
    assert_eq!(range.get((5, 1)), Some(&Data::String("one\ntwo".into())));

    // A row repeated three times in the file appears three times.
    for row in 6..9 {
        assert_eq!(
            range.get((row, 2)),
            Some(&Data::String("repeated".into())),
            "row {row} should hold the repeated value"
        );
    }
}

/// The formulas of a sheet can be read separately from its values.
#[test]
fn reads_formulas_from_an_ods_workbook() {
    let mut workbook = open_workbook(fixture("sample.ods")).unwrap();
    let formulas = workbook.worksheet_formula("Sheet1").unwrap();
    assert_eq!(
        formulas.get((4, 2)),
        Some(&"SUM([.B2:.B3])".to_string()),
        "the namespace prefix should be stripped"
    );
}

/// A small workbook exported from a bot still reads cleanly.
#[test]
fn reads_another_real_workbook() {
    let mut workbook = open_workbook(fixture("rollmilkice.xlsx")).expect("workbook should open");
    assert!(!workbook.sheet_names().is_empty());

    let sheets = workbook.worksheets().unwrap();
    assert_eq!(sheets.len(), workbook.sheet_names().len());
    // Every sheet should be readable, and at least one should carry data.
    let populated = sheets.iter().filter(|(_, r)| !r.is_empty()).count();
    assert!(populated > 0, "expected at least one populated sheet");
}

/// Sheet lookup by position agrees with lookup by name.
#[test]
fn sheets_are_addressable_by_index() {
    let mut workbook = open_workbook(fixture("chanora.xlsx")).unwrap();
    let names = workbook.sheet_names().to_vec();
    for (index, name) in names.iter().enumerate() {
        assert_eq!(workbook.sheet_index(name), Some(index));
        let by_name = workbook.worksheet_range(name).unwrap();
        let by_index = workbook.worksheet_range_at(index).unwrap();
        assert_eq!(by_name, by_index, "sheet {name} differs by lookup route");
    }
    assert!(matches!(
        workbook.worksheet_range_at(999),
        Err(Error::NotFound(_))
    ));
    assert!(matches!(
        workbook.worksheet_range("No Such Sheet"),
        Err(Error::NotFound(_))
    ));
}

/// Formats are detected from content, not from the file name.
#[test]
fn detection_ignores_the_extension() {
    // The same bytes under a misleading extension still read as ODS.
    let copy = crate::common::scratch_file("cellar-detection-probe.xlsx");
    std::fs::copy(fixture("sample.ods"), &copy).unwrap();
    let workbook = open_workbook(&copy).unwrap();
    assert_eq!(workbook.format(), Format::Ods);
    crate::common::cleanup(&copy);
}

/// A file that is not a spreadsheet is rejected rather than misread.
#[test]
fn rejects_a_file_that_is_not_a_spreadsheet() {
    // A Word document is an OLE container, so it looks plausible until the streams are listed.
    assert!(open_workbook(fixture("word97.doc")).is_err());

    // Arbitrary bytes are not any known container.
    let junk = crate::common::scratch_file("cellar-junk-probe.bin");
    std::fs::write(&junk, b"this is definitely not a workbook at all").unwrap();
    assert!(open_workbook(&junk).is_err());
    crate::common::cleanup(&junk);
}

/// Reading from an in-memory buffer matches reading from a file.
#[test]
fn reads_from_an_in_memory_buffer() {
    let bytes = std::fs::read(fixture("sample.ods")).unwrap();
    let mut workbook = cellar::open_workbook_auto_from_rs(std::io::Cursor::new(bytes)).unwrap();
    assert_eq!(workbook.sheet_names(), ["Sheet1", "Second Sheet"]);
    let range = workbook.worksheet_range("Sheet1").unwrap();
    assert_eq!(range.get((1, 0)), Some(&Data::String("alpha".into())));
}
